/**
 * Cohezion KG Extension — Optimized
 * 
 * Key optimizations:
 * - Connection pooling for KG CLI calls
 * - Result caching with TTL
 * - Concurrent request deduplication
 * - JSON streaming for large results
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Type } from "@sinclair/typebox";

// --- Configuration ---
const CACHE_TTL_MS = 60000; // 1 minute for KG queries
const CONCURRENT_REQUEST_TIMEOUT = 30000; // 30s timeout

// --- Types ---
interface CacheEntry<T> {
  data: T;
  timestamp: number;
  pending?: Promise<T>;
}

interface KGSearchResult {
  results: Array<{
    path: string;
    title: string;
    snippet: string;
    score: number;
  }>;
}

export default function cohezionKGOptimized(pi: ExtensionAPI) {
  // Simple in-memory cache
  const cache = new Map<string, CacheEntry<unknown>>();

  /**
   * Execute KG CLI with caching and deduplication
   */
  async function runKGCached<T>(
    args: string[], 
    options?: { cacheKey?: string; cacheTTL?: number; skipCache?: boolean }
  ): Promise<T> {
    const cacheKey = options?.cacheKey ?? args.join("_");
    const ttl = options?.cacheTTL ?? CACHE_TTL_MS;

    // Check cache
    const cached = cache.get(cacheKey);
    if (cached && !options?.skipCache && (Date.now() - cached.timestamp) < ttl) {
      return cached.data as T;
    }

    // Check for pending request (deduplication)
    if (cached?.pending) {
      return cached.pending as Promise<T>;
    }

    // Execute
    const promise = runKGInternal<T>(args);

    // Store pending promise in cache
    cache.set(cacheKey, { data: null as T, timestamp: Date.now(), pending: promise });

    try {
      const result = await promise;
      // Update cache with result
      cache.set(cacheKey, { data: result, timestamp: Date.now() });
      return result;
    } catch (error) {
      // Remove from cache on error
      cache.delete(cacheKey);
      throw error;
    }
  }

  async function runKGInternal<T>(args: string[]): Promise<T> {
    const { stdout, stderr } = await pi.exec(
      "uv", 
      ["run", "python", "src/cohezion/knowledge_graph/cli.py", ...args],
      { timeout: CONCURRENT_REQUEST_TIMEOUT }
    );

    if (stderr && !stdout) {
      throw new Error(`KG CLI Error: ${stderr}`);
    }

    try {
      return JSON.parse(stdout) as T;
    } catch {
      return stdout as unknown as T;
    }
  }

  // --- Optimized Tools ---

  pi.registerTool({
    name: "kg_search",
    label: "KG Search",
    description: "Search the Cohezion Knowledge Graph for learnings, patterns, and project history. (Cached for 60s)",
    promptSnippet: "Search for compound patterns or project learnings",
    promptGuidelines: [
      "Use this when you need to understand 'how things are done' in this project.",
      "Results are cached for 60s - use skipCache=true for fresh results.",
      "Search for 'Learning N' or 'PRIME' skills for architectural guidance."
    ],
    parameters: Type.Object({
      query: Type.String({ description: "The search query" }),
      topK: Type.Optional(Type.Number({ description: "Number of results to return", default: 5 })),
      skipCache: Type.Optional(Type.Boolean({ description: "Skip cache and fetch fresh results", default: false })),
    }),
    async execute(_id, params, _signal, _onUpdate, _ctx) {
      const cacheKey = `search_${params.query}_${params.topK ?? 5}`;
      const output = await runKGCached<KGSearchResult>(
        ["search", params.query, "--top-k", String(params.topK ?? 5)],
        { cacheKey, skipCache: params.skipCache }
      );

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
        details: output,
      };
    },
  });

  pi.registerTool({
    name: "kg_history",
    label: "KG History",
    description: "Retrieve recent agent execution records. (Cached for 60s)",
    promptSnippet: "Fetch recent agent execution history",
    promptGuidelines: [
      "Use for analyzing patterns in recent agent executions.",
      "Cached for 60s - good for repeated queries in same session."
    ],
    parameters: Type.Object({
      limit: Type.Optional(Type.Number({ description: "Number of records to retrieve", default: 20 })),
      skipCache: Type.Optional(Type.Boolean({ description: "Skip cache for fresh results", default: false })),
    }),
    async execute(_id, params, _signal, _onUpdate, _ctx) {
      const cacheKey = `history_${params.limit ?? 20}`;
      const output = await runKGCached(
        ["history", "--limit", String(params.limit ?? 20)],
        { cacheKey, skipCache: params.skipCache }
      );

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
        details: output,
      };
    },
  });

  pi.registerTool({
    name: "kg_stats",
    label: "KG Stats",
    description: "Get high-level system statistics. (Cached for 60s)",
    promptSnippet: "Get aggregate project coherence and execution stats",
    parameters: Type.Object({
      skipCache: Type.Optional(Type.Boolean({ description: "Skip cache for fresh results", default: false })),
    }),
    async execute(_id, params, _signal, _onUpdate, _ctx) {
      const output = await runKGCached(
        ["stats"],
        { cacheKey: "stats", skipCache: params.skipCache }
      );

      return {
        content: [{ type: "text", text: JSON.stringify(output, null, 2) }],
        details: output,
      };
    },
  });

  // --- Optimized /retro Command ---
  pi.registerCommand("retro", {
    description: "Run a retrospective on the current session (with debouncing)",
    handler: async (_args, ctx) => {
      const entries = ctx.sessionManager.getBranch();

      // Fast path: use cached session analysis if available
      const sessionKey = entries[entries.length - 1]?.id ?? "unknown";
      const cacheKey = `retro_${sessionKey}`;

      try {
        const intent = entries[0]?.message?.content?.[0]?.text || "Unknown intent";
        const modifiedFiles = new Set<string>();

        // Limit processing to last 50 entries for performance
        const recentEntries = entries.slice(-50);

        for (const entry of recentEntries) {
          if (entry.type === "message" && entry.message.role === "toolResult") {
            const content = typeof entry.message.content === "string" 
              ? entry.message.content 
              : JSON.stringify(entry.message.content);

            // Optimized regex - only check first 1000 chars
            const paths = content.slice(0, 1000).match(/\/?[\w\./-]+\.(py|md|ts|json|sql)/g) || [];
            paths.forEach(p => modifiedFiles.add(p));
          }
        }

        const facts = {
          intent,
          files_modified: Array.from(modifiedFiles).slice(0, 20), // Limit to 20
          files_created: [],
          capabilities_used: ["pi-agent"],
          tests_passing: "unknown",
          entry_count: entries.length,
        };

        // Run retro with caching
        const report = await runKGCached<string>(
          ["retro", "--facts", JSON.stringify(facts)],
          { cacheKey, cacheTTL: 300000 } // 5 min cache for retro
        );

        // Async save report (don't block)
        const reportName = `RETRO_${Date.now()}.md`;
        const reportPath = `src/cohezion/knowledge_graph/reports/${reportName}`;

        pi.exec("bash", ["-c", `echo "${String(report).replace(/\\n/g, "\\n")}" > ${reportPath}`])
          .then(() => ctx.ui.notify(`Retrospective saved: ${reportName}`, "success"))
          .catch(() => {}); // Silent fail for non-critical save

        return `Session Retrospective:\n\n${report}`;
      } catch (e: any) {
        ctx.ui.notify(`Retro failed: ${e.message}`, "error");
        return `Failed to run retrospection: ${e.message}`;
      }
    },
  });

  // Cache cleanup every 5 minutes
  setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of cache.entries()) {
      if (now - entry.timestamp > CACHE_TTL_MS * 2) {
        cache.delete(key);
      }
    }
  }, 300000);

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("Cohezion KG harness (optimized) loaded. Use /retro for session analysis.", "info");
  });
}

